import java.util.PriorityQueue;
import java.util.Queue;

public class PriorityQueueDemo {
    public static void main(String[] args) {
        // Default constructor creates a Min-Heap (natural order)
        Queue<Integer> minHeap = new PriorityQueue<>();

        minHeap.offer(45);
        minHeap.offer(12);
        minHeap.offer(89);
        minHeap.offer(7);
        minHeap.offer(23);

        // 1. Instant root inspection in O(1)
        System.out.println("Root minimum (peek): " + minHeap.peek()); // 7

        // 2. WARNING: for-each iteration prints raw array heap layout, NOT sorted order!
        System.out.print("for-each iteration:   ");
        for (int val : minHeap) {
            System.out.print(val + " ");
        }
        System.out.println();

        // 3. Proper sorted extraction: sequential poll()
        System.out.print("Sequential poll():    ");
        while (!minHeap.isEmpty()) {
            System.out.print(minHeap.poll() + " ");
        }
        System.out.println();
    }
}
// Expected Output:
// Root minimum (peek): 7
// for-each iteration:   7 12 89 45 23 
// Sequential poll():    7 12 23 45 89

