import java.util.PriorityQueue;

public class HospitalTriageEngine {
    static class Patient implements Comparable<Patient> {
        final String name;
        final int urgencyScore; // 1 = Critical, 2 = Urgent, 3 = Stable

        Patient(String name, int urgencyScore) {
            this.name = name;
            this.urgencyScore = urgencyScore;
        }

        @Override
        public int compareTo(Patient other) {
            return Integer.compare(this.urgencyScore, other.urgencyScore);
        }

        @Override
        public String toString() {
            return name + " (P" + urgencyScore + ")";
        }
    }

    public static void main(String[] args) {
        PriorityQueue<Patient> erQueue = new PriorityQueue<>();

        erQueue.offer(new Patient("Alice", 3));
        erQueue.offer(new Patient("Bob", 1));
        erQueue.offer(new Patient("Charlie", 2));
        erQueue.offer(new Patient("Diana", 1));

        System.out.println("Treating patients in urgency order:");
        while (!erQueue.isEmpty()) {
            System.out.println("Treating: " + erQueue.poll());
        }
    }
}

