import java.util.PriorityQueue;

public class KthLargest {
    private final int k;
    private final PriorityQueue<Integer> minHeap;

    public KthLargest(int k, int[] nums) {
        this.k = k;
        this.minHeap = new PriorityQueue<>(k);
        for (int num : nums) {
            add(num);
        }
    }

    public int add(int val) {
        if (minHeap.size() < k) {
            minHeap.offer(val);
        } else if (val > minHeap.peek()) {
            minHeap.poll();
            minHeap.offer(val);
        }
        return minHeap.peek();
    }

    public static void main(String[] args) {
        KthLargest tracker = new KthLargest(3, new int[]{4, 5, 8, 2});
        System.out.println(tracker.add(3));
        System.out.println(tracker.add(5));
        System.out.println(tracker.add(10));
        System.out.println(tracker.add(9));
        System.out.println(tracker.add(4));
    }
}

