import java.util.PriorityQueue;
import java.util.Arrays;

public class MergeKSorted {
    static class ArrayEntry implements Comparable<ArrayEntry> {
        final int val;
        final int arrayIndex;
        final int elementIndex;

        ArrayEntry(int val, int arrayIndex, int elementIndex) {
            this.val = val;
            this.arrayIndex = arrayIndex;
            this.elementIndex = elementIndex;
        }

        @Override
        public int compareTo(ArrayEntry other) {
            return Integer.compare(this.val, other.val);
        }
    }

    public static int[] merge(int[][] arrays) {
        int totalElements = 0;
        PriorityQueue<ArrayEntry> pq = new PriorityQueue<>();

        for (int i = 0; i < arrays.length; i++) {
            if (arrays[i] != null && arrays[i].length > 0) {
                totalElements += arrays[i].length;
                pq.offer(new ArrayEntry(arrays[i][0], i, 0));
            }
        }

        int[] result = new int[totalElements];
        int writeIndex = 0;

        while (!pq.isEmpty()) {
            ArrayEntry current = pq.poll();
            result[writeIndex++] = current.val;

            int nextElemIdx = current.elementIndex + 1;
            if (nextElemIdx < arrays[current.arrayIndex].length) {
                pq.offer(new ArrayEntry(arrays[current.arrayIndex][nextElemIdx], current.arrayIndex, nextElemIdx));
            }
        }

        return result;
    }

    public static void main(String[] args) {
        int[][] arrays = {
            {1, 4, 7},
            {2, 5, 8},
            {3, 6, 9}
        };
        System.out.println(Arrays.toString(merge(arrays)));
    }
}

