import java.util.PriorityQueue;
import java.util.List;
import java.util.ArrayList;

public class PriorityDrainer {
    public static <T> List<T> drainToSortedList(PriorityQueue<T> pq) {
        List<T> result = new ArrayList<>();
        if (pq == null) return result;
        while (!pq.isEmpty()) {
            result.add(pq.poll());
        }
        return result;
    }

    public static void main(String[] args) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        pq.offer(50);
        pq.offer(10);
        pq.offer(30);
        pq.offer(20);
        System.out.println(drainToSortedList(pq));
    }
}
